  content: var(--icon-minimize-sm);

  &:dir(rtl) {
    transform: scaleX(-1);
  }
}

.icon-maximize {
  -moz-context-properties: stroke;
  stroke: currentColor;
  content: var(--icon-maximize-sm);

  &:dir(rtl) {
    transform: scaleX(-1);
  }
}

.toggle-label {
  display: inline-block;
  line-height: 1;
  margin: 0;
  padding: 0;
}

.toggle-group,
.checkbox-group {
  display: flex;
  align-items: center;
}

.toggle-checkbox {
  appearance: none;
  box-sizing: border-box;
  padding: 0;
  background-color: var(--color-surface-lower);
  border: 1px solid var(--color-surface-border);
  block-size: 22px;
  inline-size: 44px;
  border-radius: 14px;
  cursor: pointer;

  &::before {
    display: block;
    content: "";
    box-sizing: border-box;
    background-color: var(--color-surface-base);
    border: 1px solid var(--color-surface-border);
    block-size: 18px;
    inline-size: 18px;
    margin-block-start: 1px;
    margin-inline-start: 1px;
    border-radius: 10px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
    translate: 0;
  }

  &:checked {
    background-color: var(--selected-item-color);
    border-color: color-mix(in srgb, var(--selected-item-color) 80%, black);

    &::before {
      translate: 23px;
      background-color: var(--selected-item-text-color);
      border-color: color-mix(in srgb, var(--selected-item-color) 80%, black);
    }

    &:is(:hover, :active) {
      background-color: color-mix(in srgb, var(--selected-item-color) 90%, black);
      border-color: color-mix(in srgb, var(--selected-item-color) 80%, black);
    }
  }

  &:is(:hover, :active) {
    background-color: var(--color-surface-border);
    border-color: var(--color-neutral-200);
  }

  &:focus-visible {
    outline: var(--focus-outline);
    outline-offset: var(--focus-outline-offset);
  }

  &.toggle-checkbox-sm {
    block-size: 18px;
    inline-size: 38px;

    &::before {
      block-size: 14px;
      inline-size: 14px;
    }

    &:checked::before {
      translate: 20px;
    }
  }
}

@media (prefers-color-scheme: dark) {
  .toggle-checkbox {
    background-color: color-mix(in srgb, currentColor 10%, transparent);
    border-color: color-mix(in srgb, currentColor 50%, transparent);

    &::before {
      background-color: color-mix(in srgb, currentColor 70%, transparent);
      border-color: transparent;
    }

    &:is(:hover, :active) {
      background-color: color-mix(in srgb, currentColor 20%, transparent);
      border-color: color-mix(in srgb, currentColor 50%, transparent);
    }

    &:checked {
      border-color: rgba(0, 0, 0, 0.4);

      &::before {
        border-color: color-mix(in srgb, var(--selected-item-color), black 40%);
      }

      &:is(:hover, :active) {
        background-color: color-mix(in srgb, var(--selected-item-color), black 20%);
        border-color: rgba(0, 0, 0, 0.4);
      }
    }
  }
}

@media (prefers-reduced-motion: no-preference) {
  .toggle-checkbox {
    transition:
      opacity 0.15s ease,
      background-color 0.15s ease,
      border-color 0.15s ease;

    &::before {
      transition: translate 0.21s ease;
    }
  }
}

